update public.learning_paths
set
  title = 'Community/Public Health Nursing',
  goal = 'Community/Public Health Nursing',
  summary = 'Community/Public Health Nursing prepares the BSN learner to improve health with populations and communities across the care continuum. Students use epidemiology, community-engaged assessment, health promotion, equity analysis, policy, environmental health, emergency preparedness, informatics, and evaluation to identify priorities and co-design evidence-informed action. A supervised practicum emphasizes partnership, ethical practice, clear communication, and measurable benefit.',
  data = $cphnjson${"slug": "community-public-health-nursing", "title": "Community/Public Health Nursing", "description": "Community/Public Health Nursing prepares the BSN learner to improve health with populations and communities across the care continuum. Students use epidemiology, community-engaged assessment, health promotion, equity analysis, policy, environmental health, emergency preparedness, informatics, and evaluation to identify priorities and co-design evidence-informed action. A supervised practicum emphasizes partnership, ethical practice, clear communication, and measurable benefit.", "topics": [{"id": "c8849ec1-2854-4bf8-98ff-2e4f3dd3d7dc", "type": "topic", "title": "Foundations of Community and Public Health Nursing", "description": "Shifts the learner from bedside episodes to populations, systems, prevention, partnership, and the professional identity of the public health nurse.", "children": [{"id": "ae8a1541-122f-4225-a6d2-017a3e120211", "type": "subtopic", "title": "Population, community, and public health nursing", "description": "Clarifies the unit of care and why nursing practice extends beyond individual encounters.", "children": [{"id": "8a477c1c-0102-473e-b612-f55297e80dd0", "type": "concept", "title": "population vs aggregate vs community"}, {"id": "e15acd57-9010-4eba-b99e-f3d6d16cd90d", "type": "concept", "title": "population health across the care continuum"}, {"id": "56a72ca6-1737-4b18-a540-a76b80771c06", "type": "concept", "title": "community as partner, place, identity, and system"}]}, {"id": "824c0f6a-24b3-489f-b406-663cf6a71721", "type": "subtopic", "title": "History, values, and essential functions", "description": "Connects present practice to sanitation, surveillance, social reform, and organized public health.", "children": [{"id": "4e7f467a-5aa8-4d42-8b74-c23f915efebe", "type": "concept", "title": "public health milestones and nursing pioneers"}, {"id": "1a6c64de-5f18-4c2a-baf8-fa8e931dfb58", "type": "concept", "title": "assessment, policy development, and assurance"}, {"id": "a92a14a5-5008-47f1-a7f3-3cc4ca5f2a24", "type": "concept", "title": "primary, secondary, and tertiary prevention"}]}, {"id": "9f367e8c-7d3d-4ce6-aaec-8956ab79455a", "type": "subtopic", "title": "Roles, standards, and collaboration", "description": "Shows how nurses lead, educate, investigate, advocate, coordinate, and collaborate.", "children": [{"id": "4c71b70e-bbe2-4c51-a63b-3e8012d02340", "type": "concept", "title": "public health nursing scope and standards"}, {"id": "46d07d67-c5ef-4dd4-af11-3ad0f361a013", "type": "concept", "title": "local, tribal, regional, federal, and global systems"}, {"id": "32cace05-760c-43a5-80f0-839cea6bf874", "type": "concept", "title": "interprofessional and cross-sector partnership"}]}]}, {"id": "409eeddf-d6b3-470d-ba46-9ed049a5c86b", "type": "topic", "title": "Community Partnership, Assessment, and Priority Setting", "description": "Builds reciprocal relationships, combines data with lived experience, and identifies priorities communities recognize as meaningful.", "children": [{"id": "d5ddbf24-a729-4b5b-a418-84016ebd8939", "type": "subtopic", "title": "Community engagement and power sharing", "description": "Frames residents as co-designers rather than passive recipients.", "children": [{"id": "20825454-2f15-4837-bb20-6066d7108ff0", "type": "concept", "title": "stakeholder mapping and relationship building"}, {"id": "fe761d30-d316-461a-9de1-ea30887630f7", "type": "concept", "title": "asset-based community development"}, {"id": "5d9dfff8-affd-4c3c-9842-80dcdac22ab7", "type": "concept", "title": "advisory structures and shared decisions"}]}, {"id": "59b77c3c-d06e-4000-a870-425118654e10", "type": "subtopic", "title": "Community assessment methods", "description": "Introduces systematic approaches to strengths, needs, resources, and risks.", "children": [{"id": "07c2ee31-7d1b-4b76-bea7-8958e2cde441", "type": "concept", "title": "windshield survey and observation"}, {"id": "ed87572c-dd67-4c2e-8d4f-94b990eb2284", "type": "concept", "title": "interviews, focus groups, and surveys"}, {"id": "2327f190-35d3-4660-afe5-231fe131dcb0", "type": "concept", "title": "secondary data, resource inventories, and service mapping"}]}, {"id": "ea0c2926-0436-42cb-a4f4-b06a96202a5d", "type": "subtopic", "title": "Prioritization and community diagnosis", "description": "Turns findings into defensible and actionable nursing priorities.", "children": [{"id": "466c1b86-cbaf-4cdb-995e-a7e24c2b10a3", "type": "concept", "title": "magnitude, seriousness, feasibility, and equity"}, {"id": "c138d94d-3728-4b5c-b5c3-1247bfe5165f", "type": "concept", "title": "population-focused nursing diagnosis"}, {"id": "279b1aa3-7e89-4ad4-b5f6-db984091921f", "type": "concept", "title": "community validation and priority matrices"}]}]}, {"id": "45dcf031-a17a-470c-934f-087b84af264f", "type": "topic", "title": "Epidemiology, Surveillance, and Population Data", "description": "Gives nurses the quantitative language to recognize patterns, interpret risk, investigate threats, and communicate uncertainty.", "children": [{"id": "41a0a1d0-bec3-491d-8caa-5f5fbd0911d9", "type": "subtopic", "title": "Measures of frequency and effect", "description": "Builds fluency with measures used in reports and dashboards.", "children": [{"id": "ddf8bf09-2f7d-4661-b340-8ff4399e0055", "type": "concept", "title": "incidence, prevalence, mortality, and case-fatality"}, {"id": "4c851e64-2ab3-4b2b-9b4c-be8d0bb3e147", "type": "concept", "title": "risk, rate, ratio, and odds"}, {"id": "94e99d88-1db4-4825-87af-bfe573d08d17", "type": "concept", "title": "absolute vs relative effects"}]}, {"id": "6d89f110-d88a-4ea3-9519-fa30119c2b5c", "type": "subtopic", "title": "Study designs, bias, and causality", "description": "Helps learners judge associations and identify likely error.", "children": [{"id": "30017ec9-d287-491a-8106-4c3b5d597f0e", "type": "concept", "title": "descriptive and analytic designs"}, {"id": "f89fb4f5-00cf-471a-